#define RAW_HANDLER(nm, enc, bts, endi, desc) \
  { nm, 0, raw_startread, raw_read, raw_stop, raw_startwrite, raw_write, raw_stop, NULL, desc, nm##_names, NULL }

static int raw8u_startread(sox_format_t * ft); /* placeholder */

const sox_format_handler_t sox_raw_handler =
  RAW_HANDLER(raw, SOX_ENCODING_SIGN2, 16, 0, "Raw audio");
static const sox_format_handler_t s8_h = RAW_HANDLER(s8, SOX_ENCODING_SIGN2, 8, 0, "Raw signed 8 bit");
