    wr_le32f(ft, 18);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
    wr_le16f(ft, 0);           /* cbSize */
  } else {
    wr_le32f(ft, 16);
    wr_le16f(ft, tag);
    wr_le16f(ft, channels);
    wr_le32f(ft, rate);
    wr_le32f(ft, avg);
    wr_le16f(ft, blockalign);
    wr_le16f(ft, bits);
  }
