/* xsox - effects: engine + basic effects */
#include "xsox.h"
#include <ctype.h>
#include <errno.h>

/* ---------- effect registry entry ---------- */

#define EFF(name) static const sox_effect_handler_t name##_h
extern const sox_effect_handler_t * const sox_effect_handlers[];

const sox_effect_handler_t * sox_find_effect(const char * name)
{
  int i;
  for (i = 0; sox_effect_handlers[i]; i++)
    if (!strcmp(name, sox_effect_handlers[i]->name))
      return sox_effect_handlers[i];
  return NULL;
}

effect_t * sox_create_effect(const sox_effect_handler_t * h)
{
  effect_t * e = calloc(1, sizeof *e);
  e->handler = h;
  e->name = strdup(h->name);
  return e;
}

void sox_delete_effect(effect_t * e)
{
  if (!e) return;
  free(e->rbuf);
  free(e->priv);
  free(e->name);
  free(e);
}

/* ---------- input helpers ---------- */

/* fill residual buffer up to want samples; returns available */
static size_t eff_fill(effect_t * e, size_t want)
{
  while (e->rlen < want && !e->in_eof) {
    size_t need = want - e->rlen;
    size_t got;
    if (e->rcap < e->rlen + need) {
      e->rcap = (e->rlen + need) * 2;
      e->rbuf = realloc(e->rbuf, e->rcap * sizeof(sox_sample_t));
    }
    got = e->input(e, e->rbuf + e->rlen, need);
    if (got == 0) e->in_eof = 1;
    e->rlen += got;
    e->total_in += got;
  }
  return e->rlen;
}

static void eff_consume(effect_t * e, size_t n)
{
  if (n >= e->rlen) { e->rlen = 0; return; }
  memmove(e->rbuf, e->rbuf + n, (e->rlen - n) * sizeof(sox_sample_t));
  e->rlen -= n;
}

/* clip counting */
static sox_sample_t eclip(effect_t * e, double v)
{
  if (v > SOX_SAMPLE_MAX) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MAX; }
  if (v < SOX_SAMPLE_MIN) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MIN; }
  return (sox_sample_t)v;
}

/* parse a number with optional k/M suffix */
static double parse_num(const char * s, int * ok)
{
  char * end;
  double v = strtod(s, &end);
  *ok = 1;
  if (*end == 'k' || *end == 'K') { v *= 1000; end++; }
  else if (*end == 'M') { v *= 1000000; end++; }
  if (*end || end == s) *ok = 0;
  return v;
}

/* parse time/position spec: returns samples; kind: 0=time,1=samples,2=relative(+/-) */
uint64_t sox_parse_position(const char * s, const sox_signalinfo_t * sig, int * is_samples, int * relative)
{
  double v = 0;
  int ok = 0;
  *is_samples = 0;
  *relative = 0;
  if (!s || !*s) return 0;
  if (*s == '+') { *relative = 1; s++; }
  else if (*s == '-') { *relative = -1; s++; }
  if (*s == '=') { s++; }
  {
    size_t l = strlen(s);
    if (l && s[l-1] == 's') {
      /* samples */
      char * tmp = strndup(s, l - 1);
      v = strtod(tmp, NULL);
      free(tmp);
      *is_samples = 1;
      ok = 1;
    } else if (strchr(s, ':')) {
      /* hh:mm:ss.frac or mm:ss.frac */
      double t = 0;
      char * dup = strdup(s);
      char * p = dup;
      char * parts[4]; int n = 0;
      char * tok = strtok(p, ":");
      while (tok && n < 4) { parts[n++] = tok; tok = strtok(NULL, ":"); }
      if (n == 2) t = strtod(parts[0], NULL) * 60 + strtod(parts[1], NULL);
      else if (n == 3) t = strtod(parts[0], NULL) * 3600 + strtod(parts[1], NULL) * 60 + strtod(parts[2], NULL);
      else t = strtod(s, NULL);
      free(dup);
      v = t * sig->rate;
      ok = 1;
    } else {
      v = strtod(s, NULL) * sig->rate;
      ok = 1;
    }
  }
  (void)ok;
  if (v < 0) v = -v;
  return (uint64_t)(v + 0.5);
}

/* ================================================================ */
/* vol */
typedef struct { double gain; } vol_t;

static int vol_getopts(effect_t * e, int argc, char ** argv)
{
  vol_t * v = calloc(1, sizeof *v);
  char * end;
  e->priv = v;
  if (argc < 1) return -1;
  v->gain = strtod(argv[0], &end);
  if (end == argv[0]) return -1;
  if (!strcmp(end, "dB")) v->gain = pow(10.0, v->gain / 20.0);
  else if (*end) {
    if (!strcmp(end, "e")) v->gain = pow(10.0, v->gain / 20.0); /* power? handled later */
  }
  return 0;
}
static int vol_start(effect_t * e) { return 0; }
static size_t vol_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  vol_t * v = e->priv;
  size_t n = is < omax ? is : omax, i;
  for (i = 0; i < n; i++) ob[i] = eclip(e, ib[i] * v->gain);
  e->consumed = n;
  return n;
}
EFF(vol) = {"vol", "GAIN [TYPE [LIMITERGAIN]]", NULL, vol_getopts, vol_start, vol_flow, NULL, NULL, 0};

/* gain: like vol but dB default, plus -n/-e/-b/-l flags handled in getopts */
static int gain_getopts(effect_t * e, int argc, char ** argv)
{
  vol_t * v = calloc(1, sizeof *v);
  int i;
  e->priv = v;
  v->gain = 1.0;
  for (i = 0; i < argc; i++) {
    if (argv[i][0] == '-') {
      /* flags -n -e -b -l -r: unimplemented flags tolerated */
      continue;
    }
    v->gain *= pow(10.0, strtod(argv[i], NULL) / 20.0);
  }
  return 0;
}
EFF(gain) = {"gain", "[-e|-b|-l|-n] [gain-dB]", NULL, gain_getopts, vol_start, vol_flow, NULL, NULL, 0};

/* ================================================================ */
/* trim */
typedef struct {
  uint64_t start, length;  /* samples per channel */
  int has_length;
  uint64_t pos;            /* current frame pos */
} trim_t;

static int trim_getopts(effect_t * e, int argc, char ** argv)
{
  trim_t * t = calloc(1, sizeof *t);
  e->priv = t;
  if (argc < 1) return -1;
  {
    int is_samp, rel;
    t->start = sox_parse_position(argv[0], &e->in_signal, &is_samp, &rel);
  }
  if (argc > 1) {
    int is_samp, rel;
    t->length = sox_parse_position(argv[1], &e->in_signal, &is_samp, &rel);
    if (rel < 0) {
      /* length relative to end: needs total length; handled at start */
      t->has_length = 2;
    } else if (rel > 0) {
      t->has_length = 1; /* +n means from start */
    } else {
      /* absolute end position: sox treats second arg as length unless '=' prefix */
      t->has_length = 1;
    }
  } else t->has_length = 0;
  return 0;
}
static int trim_start(effect_t * e)
{
  trim_t * t = e->priv;
  (void)e;
  t->pos = 0;
  if (t->has_length == 2 && e->in_signal.length) {
    uint64_t total = e->in_signal.length / (e->in_signal.channels ? e->in_signal.channels : 1);
    t->length = total > t->length + t->start ? total - t->start - t->length : 0;
    t->has_length = 1;
  }
  return 0;
}
static size_t trim_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  trim_t * t = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch, oframes = 0;
  size_t i = 0;
  while (i < nframes && oframes * ch < omax) {
    uint64_t p = t->pos;
    int keep = 0;
    if (p >= t->start && (!t->has_length || p - t->start < t->length)) keep = 1;
    if (keep) {
      unsigned c;
      for (c = 0; c < ch && oframes * ch + c < omax; c++)
        ob[oframes * ch + c] = ib[i * ch + c];
      oframes++;
    }
    t->pos++;
    i++;
    if (t->has_length && t->pos >= t->start + t->length && t->has_length) {
      /* can stop early; consume rest and signal done by just passing through */
      break;
    }
  }
  e->consumed = i * ch;
  return oframes * ch;
}
EFF(trim) = {"trim", "{POSITION}", NULL, trim_getopts, trim_start, trim_flow, NULL, NULL, 0};

/* ================================================================ */
/* pad: pad {length[@position]} */
typedef struct {
  uint64_t pre, post;      /* frames (simplified: pre at 0, post at end) */
  uint64_t emitted;        /* post zeros emitted */
  int started;
} pad_t;

static int pad_getopts(effect_t * e, int argc, char ** argv)
{
  pad_t * p = calloc(1, sizeof *p);
  int i;
  e->priv = p;
  for (i = 0; i < argc; i++) {
    char * at = strchr(argv[i], '@');
    int is_samp, rel;
    if (at) *at = 0;
    {
      uint64_t n = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
      if (at) {
        /* at position */
        uint64_t pos = sox_parse_position(at + 1, &e->in_signal, &is_samp, &rel);
        if (pos == 0) p->pre = n; /* simplification */
        else p->pre = n; /* unsupported middle pad: approximate at 0 */
        (void)pos;
      } else {
        if (i == 0) p->pre = n; else p->post = n;
      }
    }
  }
  return 0;
}
static int pad_start(effect_t * e) { pad_t * p = e->priv; p->emitted = 0; p->started = 0; return 0; }
static size_t pad_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t out = 0;
  /* emit pre zeros first */
  if (!p->started) {
    uint64_t n = p->pre * ch;
    if (n > omax) n = omax;
    memset(ob, 0, n * sizeof(sox_sample_t));
    out += n;
    p->started = 1;
    if (out == omax) { p->pre -= out / ch; p->started = p->pre == 0; e->consumed = 0; return out; }
    p->pre = 0;
  }
  {
    size_t n = is;
    if (n > omax - out) n = omax - out;
    memcpy(ob + out, ib, n * sizeof(sox_sample_t));
    out += n;
    e->consumed = n;
  }
  return out;
}
static size_t pad_drain(effect_t * e, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  uint64_t remain = (p->post - p->emitted) * ch;
  size_t n = remain > omax ? omax : (size_t)remain;
  memset(ob, 0, n * sizeof(sox_sample_t));
  p->emitted += n / ch;
  return n;
}
EFF(pad) = {"pad", "{LENGTH[@POSITION]}", NULL, pad_getopts, pad_start, pad_flow, pad_drain, NULL, 0};

/* ================================================================ */
/* repeat count */
typedef struct { uint64_t count, done; } repeat_t;
static int repeat_getopts(effect_t * e, int argc, char ** argv)
{
  repeat_t * r = calloc(1, sizeof *r);
  e->priv = r;
  if (argc < 1) return -1;
  r->count = strtoull(argv[0], NULL, 10);
  return 0;
}
static int repeat_start(effect_t * e) { ((repeat_t *)e->priv)->done = 0; return 0; }
static size_t repeat_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  size_t n = is < omax ? is : omax;
  memcpy(ob, ib, n * sizeof(sox_sample_t));
  e->consumed = n;
  return n;
}
/* repeat needs input restart support: handled by engine via flag */
EFF(repeat) = {"repeat", "COUNT", NULL, repeat_getopts, repeat_start, repeat_flow, NULL, NULL, 0};

/* ================================================================ */
/* reverse: buffer all, emit reversed frames */
typedef struct {
  sox_sample_t * buf;
  size_t len, cap;
  size_t pos;
  int draining;
} reverse_t;
static int reverse_getopts(effect_t * e, int argc, char ** argv)
{ (void)argc; (void)argv; e->priv = calloc(1, sizeof(reverse_t)); return 0; }
static int reverse_start(effect_t * e) { return 0; }
static size_t reverse_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  reverse_t * r = e->priv;
  if (r->len + is > r->cap) {
    r->cap = (r->len + is) * 2;
    r->buf = realloc(r->buf, r->cap * sizeof(sox_sample_t));
  }
  memcpy(r->buf + r->len, ib, is * sizeof(sox_sample_t));
  r->len += is;
  e->consumed = is;
  (void)ob; (void)omax;
  return 0;
}
static size_t reverse_drain(effect_t * e, sox_sample_t * ob, size_t omax)
{
  reverse_t * r = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t out = 0;
  size_t nframes = r->len / ch;
  while (out + ch <= omax && r->pos < nframes) {
    size_t f = nframes - 1 - r->pos;
    unsigned c;
    for (c = 0; c < ch; c++) ob[out + c] = r->buf[f * ch + c];
    out += ch;
    r->pos++;
  }
  return out;
}
EFF(reverse) = {"reverse", NULL, NULL, reverse_getopts, reverse_start, reverse_flow, reverse_drain, NULL, 0};

/* ================================================================ */
/* channels n: mix to n channels */
static int channels_getopts(effect_t * e, int argc, char ** argv)
{
  int * n = malloc(sizeof(int));
  e->priv = n;
  if (argc < 1) return -1;
  *n = atoi(argv[0]);
  if (*n < 1) return -1;
  return 0;
}
static int channels_start(effect_t * e)
{
  e->out_signal.channels = *(int *)e->priv;
  return 0;
}
static size_t channels_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  unsigned ich = e->in_signal.channels, och = *(int *)e->priv;
  size_t nframes = is / ich, i, maxout = omax / och, out = 0;
  if (!ich) ich = 1;
  if (nframes > maxout) nframes = maxout;
  for (i = 0; i < nframes; i++) {
    if (och == ich) {
      unsigned c;
      for (c = 0; c < och; c++) ob[i * och + c] = ib[i * ich + c];
    } else if (och == 1) {
      double sum = 0;
      unsigned c;
      for (c = 0; c < ich; c++) sum += ib[i * ich + c];
      ob[i] = eclip(e, sum / ich);
    } else if (ich == 1 && och == 2) {
      ob[i * 2] = ib[i]; ob[i * 2 + 1] = ib[i];
    } else {
      unsigned c;
      for (c = 0; c < och; c++) ob[i * och + c] = c < ich ? ib[i * ich + c] : 0;
    }
    out += och;
  }
  e->consumed = nframes * ich;
  return out;
}
EFF(channels) = {"channels", "CHANNELS", NULL, channels_getopts, channels_start, channels_flow, NULL, NULL, 0};

/* ================================================================ */
/* fade */
typedef struct {
  uint64_t in_len, out_len;   /* frames */
  uint64_t in_done, out_total;
  uint64_t total;             /* total frames (for fade out) */
  char type;                  /* t q h l p */
  int do_in, do_out;
} fade_t;

static double fade_gain(char type, double x)
{
  switch (type) {
    case 'q': return x * x * x; /* quartic? placeholder */
    case 'h': return (1 - cos(x * M_PI)) / 2; /* sine? */
    case 'l': default: return x;
    case 'p': return x * x * (3 - 2 * x);
  }
}

static int fade_getopts(effect_t * e, int argc, char ** argv)
{
  fade_t * f = calloc(1, sizeof *f);
  int i = 0;
  e->priv = f;
  f->type = 't';
  f->do_in = 0; f->do_out = 0;
  if (argc > 0 && argv[0][0] && strchr("tqhlop", argv[0][0]) && !argv[0][1]) {
    f->type = argv[0][0];
    i = 1;
  }
  if (i < argc) {
    int is_samp, rel;
    f->in_len = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
    if (f->in_len) f->do_in = 1;
    i++;
  }
  if (i < argc) {
    int is_samp, rel;
    /* stop position for fade-in (ignored: length only), then fade-out length */
    i++;
  }
  if (i < argc) {
    int is_samp, rel;
    f->out_len = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
    if (f->out_len) f->do_out = 1;
  }
  return 0;
}
static int fade_start(effect_t * e)
{
  fade_t * f = e->priv;
  f->in_done = 0;
  if (e->in_signal.length)
    f->total = e->in_signal.length / (e->in_signal.channels ? e->in_signal.channels : 1);
  else
    f->total = 0;
  return 0;
}
static size_t fade_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  fade_t * f = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch;
  if (nframes * ch > omax) nframes = omax / ch;
  size_t i;
  for (i = 0; i < nframes; i++) {
    double g = 1.0;
    uint64_t p = f->in_done + i;
    if (f->do_in && p < f->in_len) {
      double x = (double)p / (double)f->in_len;
      g *= fade_gain(f->type, x);
    }
    if (f->do_out && f->total) {
      uint64_t out_start = f->total > f->out_len ? f->total - f->out_len : 0;
      if (p >= out_start) {
        double x = (double)(f->total - p) / (double)f->out_len;
        g *= fade_gain(f->type, x);
      }
    }
    {
      unsigned c;
      for (c = 0; c < ch; c++) ob[i * ch + c] = eclip(e, ib[i * ch + c] * g);
    }
  }
  f->in_done += nframes;
  e->consumed = nframes * ch;
  return nframes * ch;
}
EFF(fade) = {"fade", "[TYPE] FADE-IN-LENGTH [STOP-TIME [FADE-OUT-LENGTH]]", NULL, fade_getopts, fade_start, fade_flow, NULL, NULL, 0};

/* ================================================================ */
/* speed factor: changes rate */
static int speed_getopts(effect_t * e, int argc, char ** argv)
{
  double * d = malloc(sizeof(double));
  e->priv = d;
  if (argc < 1) return -1;
  *d = strtod(argv[0], NULL);
  return 0;
}
static int speed_start(effect_t * e)
{
  e->out_signal.rate = e->in_signal.rate * *(double *)e->priv;
  return 0;
}
static size_t speed_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  size_t n = is < omax ? is : omax;
  memcpy(ob, ib, n * sizeof(sox_sample_t));
  e->consumed = n;
  return n;
}
EFF(speed) = {"speed", "factor[c]", NULL, speed_getopts, speed_start, speed_flow, NULL, NULL, 0};

/* ================================================================ */
/* dcshift shift [limitergain] */
static int dcshift_getopts(effect_t * e, int argc, char ** argv)
{
  double * d = malloc(sizeof(double));
  e->priv = d;
  if (argc < 1) return -1;
  *d = strtod(argv[0], NULL);
  return 0;
}
static size_t dcshift_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  double shift = *(double *)e->priv;
  size_t n = is < omax ? is : omax, i;
  double d = shift * (SOX_SAMPLE_MAX + 1.0);
  for (i = 0; i < n; i++) ob[i] = eclip(e, ib[i] + d);
  e->consumed = n;
  return n;
}
EFF(dcshift) = {"dcshift", "shift [limitergain]", NULL, dcshift_getopts, vol_start, dcshift_flow, NULL, NULL, 0};

/* ================================================================ */
/* swap: swap stereo channels */
static size_t swap_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  size_t n = is < omax ? is : omax, i;
  if (e->in_signal.channels == 2) {
    for (i = 0; i + 1 < n; i += 2) { ob[i] = ib[i+1]; ob[i+1] = ib[i]; }
  } else {
    memcpy(ob, ib, n * sizeof(sox_sample_t));
  }
  e->consumed = n;
  return n;
}
EFF(swap) = {"swap", NULL, NULL, NULL, NULL, swap_flow, NULL, NULL, 0};

/* ================================================================ */
/* upsample factor (zero-order hold? inserts zeros?) */
static int upsample_getopts(effect_t * e, int argc, char ** argv)
{
  int * n = malloc(sizeof(int));
  e->priv = n;
  if (argc < 1) return -1;
  *n = atoi(argv[0]);
  return 0;
}
static int upsample_start(effect_t * e)
{
  e->out_signal.rate = e->in_signal.rate * *(int *)e->priv;
  return 0;
}
static size_t upsample_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  int f = *(int *)e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch, i, out = 0;
  while (nframes && out + (size_t)f * ch <= omax) {
    int k;
    for (k = 0; k < f; k++) {
      unsigned c;
      for (c = 0; c < ch; c++) ob[out + c] = k == 0 ? ib[out / f / ch * ch * 0 + (out/ch/f)*ch + c] : 0;
      out += ch;
    }
    nframes--;
    i = 0; (void)i;
  }
  e->consumed = (out / f);
  return out;
}
EFF(upsample) = {"upsample", "factor", NULL, upsample_getopts, upsample_start, upsample_flow, NULL, NULL, 0};

/* downsample factor: keep every f-th sample */
static int downsample_getopts(effect_t * e, int argc, char ** argv)
{
  int * n = malloc(sizeof(int));
  e->priv = n;
  if (argc < 1) return -1;
  *n = atoi(argv[0]);
  return 0;
}
static int downsample_start(effect_t * e)
{
  e->out_signal.rate = e->in_signal.rate / *(int *)e->priv;
  return 0;
}
static size_t downsample_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  int f = *(int *)e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch, i, out = 0;
  for (i = 0; i < nframes && out + ch <= omax; i += f) {
    unsigned c;
    for (c = 0; c < ch; c++) ob[out + c] = ib[i * ch + c];
    out += ch;
  }
  e->consumed = nframes * ch;
  return out;
}
EFF(downsample) = {"downsample", "factor", NULL, downsample_getopts, downsample_start, downsample_flow, NULL, NULL, 0};

/* divide n: keep every n-th sample (rate unchanged?) */
static int divide_getopts(effect_t * e, int argc, char ** argv)
{
  int * n = malloc(sizeof(int));
  e->priv = n;
  if (argc < 1) return -1;
  *n = atoi(argv[0]);
  return 0;
}
EFF(divide) = {"divide", "factor", NULL, divide_getopts, downsample_start, downsample_flow, NULL, NULL, 0};

/* ================================================================ */
/* remix: channel mapping */
typedef struct { int out_ch; int in_map[64]; double vol[64]; int n_in[64]; } remix_t;
static int remix_getopts(effect_t * e, int argc, char ** argv)
{
  remix_t * r = calloc(1, sizeof *r);
  int i, maxo = 0;
  e->priv = r;
  if (argc < 1) return -1;
  for (i = 0; i < argc && i < 64; i++) {
    char * s = argv[i];
    int n = 0;
    r->n_in[i] = 0;
    if (!strcmp(s, "0") || !strcmp(s, "-")) { r->n_in[i] = 0; r->in_map[i] = -1; }
    else {
      char * save = NULL;
      char * tok = strtok_r(s, ",", &save);
      while (tok && n < 8) {
        /* forms: N or NvV */
        char * v = strchr(tok, 'v');
        double vol = 1.0;
        int chn;
        if (v) { *v = 0; vol = strtod(v + 1, NULL); }
        chn = atoi(tok);
        if (chn < 1) return -1;
        r->in_map[i * 8 + n] = chn - 1;
        r->vol[i * 8 + n] = vol;
        n++;
        tok = strtok_r(NULL, ",", &save);
      }
      r->n_in[i] = n;
    }
    if (i + 1 > maxo) maxo = i + 1;
  }
  r->out_ch = maxo;
  return 0;
}
static int remix_start(effect_t * e)
{
  e->out_signal.channels = ((remix_t *)e->priv)->out_ch;
  return 0;
}
static size_t remix_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  remix_t * r = e->priv;
  unsigned ich = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ich, i, out = 0;
  while (nframes && out + (size_t)r->out_ch <= omax) {
    int oc;
    for (oc = 0; oc < r->out_ch; oc++) {
      if (r->n_in[oc] == 0) ob[out + oc] = 0;
      else {
        double sum = 0;
        int k;
        for (k = 0; k < r->n_in[oc]; k++) {
          int ic = r->in_map[oc * 8 + k];
          if ((unsigned)ic < ich) sum += ib[out / r->out_ch * ich + ic] * r->vol[oc * 8 + k];
        }
        ob[out + oc] = eclip(e, sum / r->n_in[oc]);
      }
    }
    out += r->out_ch;
    nframes--;
  }
  e->consumed = out / r->out_ch * ich;
  return out;
}
EFF(remix) = {"remix", "-a|m|s|u|v|p|1|2|3|4 {i[,j]}", NULL, remix_getopts, remix_start, remix_flow, NULL, NULL, 0};

/* ================================================================ */
/* registry */

const sox_effect_handler_t * const sox_effect_handlers[] = {
  &vol_h, &gain_h, &trim_h, &pad_h, &repeat_h, &reverse_h,
  &channels_h, &remix_h, &fade_h, &speed_h, &dcshift_h, &swap_h,
  &upsample_h, &downsample_h,
  NULL
};

