/* xsox - effects: engine + basic effects */
#include "xsox.h"
#include <ctype.h>
#include <errno.h>

/* ---------- effect registry entry ---------- */

#define EFF(name) static const sox_effect_handler_t name##_h
extern const sox_effect_handler_t * const sox_effect_handlers[];

const sox_effect_handler_t * sox_find_effect(const char * name)
{
  int i;
  for (i = 0; sox_effect_handlers[i]; i++)
    if (!strcmp(name, sox_effect_handlers[i]->name))
      return sox_effect_handlers[i];
  return NULL;
}

effect_t * sox_create_effect(const sox_effect_handler_t * h)
{
  effect_t * e = calloc(1, sizeof *e);
  e->handler = h;
  e->name = strdup(h->name);
  return e;
}

void sox_delete_effect(effect_t * e)
{
  if (!e) return;
  free(e->rbuf);
  free(e->priv);
  free(e->name);
  free(e);
}

/* ---------- input helpers ---------- */

/* fill residual buffer up to want samples; returns available */
static size_t eff_fill(effect_t * e, size_t want)
{
  while (e->rlen < want && !e->in_eof) {
    size_t need = want - e->rlen;
    size_t got;
    if (e->rcap < e->rlen + need) {
      e->rcap = (e->rlen + need) * 2;
      e->rbuf = realloc(e->rbuf, e->rcap * sizeof(sox_sample_t));
    }
    got = e->input(e, e->rbuf + e->rlen, need);
    if (got == 0) e->in_eof = 1;
    e->rlen += got;
    e->total_in += got;
  }
  return e->rlen;
}

static void eff_consume(effect_t * e, size_t n)
{
  if (n >= e->rlen) { e->rlen = 0; return; }
  memmove(e->rbuf, e->rbuf + n, (e->rlen - n) * sizeof(sox_sample_t));
  e->rlen -= n;
}

/* clip counting */
static sox_sample_t eclip(effect_t * e, double v)
{
  if (v > SOX_SAMPLE_MAX) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MAX; }
  if (v < SOX_SAMPLE_MIN) { e->clips++; return (sox_sample_t)SOX_SAMPLE_MIN; }
  return (sox_sample_t)v;
}

/* parse a number with optional k/M suffix */
static double parse_num(const char * s, int * ok)
{
  char * end;
  double v = strtod(s, &end);
  *ok = 1;
  if (*end == 'k' || *end == 'K') { v *= 1000; end++; }
  else if (*end == 'M') { v *= 1000000; end++; }
  if (*end || end == s) *ok = 0;
  return v;
}

/* parse time/position spec: returns samples; kind: 0=time,1=samples,2=relative(+/-) */
uint64_t sox_parse_position(const char * s, const sox_signalinfo_t * sig, int * is_samples, int * relative)
{
  double v = 0;
  int ok = 0;
  *is_samples = 0;
  *relative = 0;
  if (!s || !*s) return 0;
  if (*s == '+') { *relative = 1; s++; }
  else if (*s == '-') { *relative = -1; s++; }
  if (*s == '=') { s++; }
  {
    size_t l = strlen(s);
    if (l && s[l-1] == 's') {
      /* samples */
      char * tmp = strndup(s, l - 1);
      v = strtod(tmp, NULL);
      free(tmp);
      *is_samples = 1;
      ok = 1;
    } else if (strchr(s, ':')) {
      /* hh:mm:ss.frac or mm:ss.frac */
      double t = 0;
      char * dup = strdup(s);
      char * p = dup;
      char * parts[4]; int n = 0;
      char * tok = strtok(p, ":");
      while (tok && n < 4) { parts[n++] = tok; tok = strtok(NULL, ":"); }
      if (n == 2) t = strtod(parts[0], NULL) * 60 + strtod(parts[1], NULL);
      else if (n == 3) t = strtod(parts[0], NULL) * 3600 + strtod(parts[1], NULL) * 60 + strtod(parts[2], NULL);
      else t = strtod(s, NULL);
      free(dup);
      v = t * sig->rate;
      ok = 1;
    } else {
      v = strtod(s, NULL) * sig->rate;
      ok = 1;
    }
  }
  (void)ok;
  if (v < 0) v = -v;
  return (uint64_t)(v + 0.5);
}

/* ================================================================ */
/* vol */
typedef struct { double gain; } vol_t;

static int vol_getopts(effect_t * e, int argc, char ** argv)
{
  vol_t * v = calloc(1, sizeof *v);
  char * end;
  e->priv = v;
  if (argc < 1) return -1;
  v->gain = strtod(argv[0], &end);
  if (end == argv[0]) return -1;
  if (!strcmp(end, "dB")) v->gain = pow(10.0, v->gain / 20.0);
  else if (*end) {
    if (!strcmp(end, "e")) v->gain = pow(10.0, v->gain / 20.0); /* power? handled later */
  }
  return 0;
}
static int vol_start(effect_t * e) { return 0; }
static size_t vol_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  vol_t * v = e->priv;
  size_t n = is < omax ? is : omax, i;
  for (i = 0; i < n; i++) ob[i] = eclip(e, ib[i] * v->gain);
  e->consumed = n;
  return n;
}
EFF(vol) = {"vol", "GAIN [TYPE [LIMITERGAIN]]", NULL, vol_getopts, vol_start, vol_flow, NULL, NULL, 0};

/* gain: like vol but dB default, plus -n/-e/-b/-l flags handled in getopts */
static int gain_getopts(effect_t * e, int argc, char ** argv)
{
  vol_t * v = calloc(1, sizeof *v);
  int i;
  e->priv = v;
  v->gain = 1.0;
  for (i = 0; i < argc; i++) {
    if (argv[i][0] == '-') {
      /* flags -n -e -b -l -r: unimplemented flags tolerated */
      continue;
    }
    v->gain *= pow(10.0, strtod(argv[i], NULL) / 20.0);
  }
  return 0;
}
EFF(gain) = {"gain", "[-e|-b|-l|-n] [gain-dB]", NULL, gain_getopts, vol_start, vol_flow, NULL, NULL, 0};

/* ================================================================ */
/* trim */
typedef struct {
  uint64_t start, length;  /* samples per channel */
  int has_length;
  uint64_t pos;            /* current frame pos */
} trim_t;

static int trim_getopts(effect_t * e, int argc, char ** argv)
{
  trim_t * t = calloc(1, sizeof *t);
  e->priv = t;
  if (argc < 1) return -1;
  {
    int is_samp, rel;
    t->start = sox_parse_position(argv[0], &e->in_signal, &is_samp, &rel);
  }
  if (argc > 1) {
    int is_samp, rel;
    t->length = sox_parse_position(argv[1], &e->in_signal, &is_samp, &rel);
    if (rel < 0) {
      /* length relative to end: needs total length; handled at start */
      t->has_length = 2;
    } else if (rel > 0) {
      t->has_length = 1; /* +n means from start */
    } else {
      /* absolute end position: sox treats second arg as length unless '=' prefix */
      t->has_length = 1;
    }
  } else t->has_length = 0;
  return 0;
}
static int trim_start(effect_t * e)
{
  trim_t * t = e->priv;
  (void)e;
  t->pos = 0;
  if (t->has_length == 2 && e->in_signal.length) {
    uint64_t total = e->in_signal.length / (e->in_signal.channels ? e->in_signal.channels : 1);
    t->length = total > t->length + t->start ? total - t->start - t->length : 0;
    t->has_length = 1;
  }
  return 0;
}
static size_t trim_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  trim_t * t = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t nframes = is / ch, oframes = 0;
  size_t i = 0;
  while (i < nframes && oframes * ch < omax) {
    uint64_t p = t->pos;
    int keep = 0;
    if (p >= t->start && (!t->has_length || p - t->start < t->length)) keep = 1;
    if (keep) {
      unsigned c;
      for (c = 0; c < ch && oframes * ch + c < omax; c++)
        ob[oframes * ch + c] = ib[i * ch + c];
      oframes++;
    }
    t->pos++;
    i++;
    if (t->has_length && t->pos >= t->start + t->length && t->has_length) {
      /* can stop early; consume rest and signal done by just passing through */
      break;
    }
  }
  e->consumed = i * ch;
  return oframes * ch;
}
EFF(trim) = {"trim", "{POSITION}", NULL, trim_getopts, trim_start, trim_flow, NULL, NULL, 0};

/* ================================================================ */
/* pad: pad {length[@position]} */
typedef struct {
  uint64_t pre, post;      /* frames (simplified: pre at 0, post at end) */
  uint64_t emitted;        /* post zeros emitted */
  int started;
} pad_t;

static int pad_getopts(effect_t * e, int argc, char ** argv)
{
  pad_t * p = calloc(1, sizeof *p);
  int i;
  e->priv = p;
  for (i = 0; i < argc; i++) {
    char * at = strchr(argv[i], '@');
    int is_samp, rel;
    if (at) *at = 0;
    {
      uint64_t n = sox_parse_position(argv[i], &e->in_signal, &is_samp, &rel);
      if (at) {
        /* at position */
        uint64_t pos = sox_parse_position(at + 1, &e->in_signal, &is_samp, &rel);
        if (pos == 0) p->pre = n; /* simplification */
        else p->pre = n; /* unsupported middle pad: approximate at 0 */
        (void)pos;
      } else {
        if (i == 0) p->pre = n; else p->post = n;
      }
    }
  }
  return 0;
}
static int pad_start(effect_t * e) { pad_t * p = e->priv; p->emitted = 0; p->started = 0; return 0; }
static size_t pad_flow(effect_t * e, const sox_sample_t * ib, size_t is, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  size_t out = 0;
  /* emit pre zeros first */
  if (!p->started) {
    uint64_t n = p->pre * ch;
    if (n > omax) n = omax;
    memset(ob, 0, n * sizeof(sox_sample_t));
    out += n;
    p->started = 1;
    if (out == omax) { p->pre -= out / ch; p->started = p->pre == 0; e->consumed = 0; return out; }
    p->pre = 0;
  }
  {
    size_t n = is;
    if (n > omax - out) n = omax - out;
    memcpy(ob + out, ib, n * sizeof(sox_sample_t));
    out += n;
    e->consumed = n;
  }
  return out;
}
static size_t pad_drain(effect_t * e, sox_sample_t * ob, size_t omax)
{
  pad_t * p = e->priv;
  unsigned ch = e->in_signal.channels ? e->in_signal.channels : 1;
  uint64_t remain = (p->post - p->emitted) * ch;
  size_t n = remain > omax ? omax : (size_t)remain;
  memset(ob, 0, n * sizeof(sox_sample_t));
  p->emitted += n / ch;
  return n;
}
