  {"s32",  SOX_ENCODING_SIGN2, 32, 0, 8000, 1},
  {"u32",  SOX_ENCODING_UNSIGNED, 32, 0, 8000, 1},
  {"s1",   SOX_ENCODING_SIGN2, 8, -1, 8000, 1},
  {"s2",   SOX_ENCODING_SIGN2, 16, -1, 8000, 1},
  {"s3",   SOX_ENCODING_SIGN2, 24, -1, 8000, 1},
  {"s4",   SOX_ENCODING_SIGN2, 32, -1, 8000, 1},
  {"u1",   SOX_ENCODING_UNSIGNED, 8, -1, 8000, 1},
  {"u2",   SOX_ENCODING_UNSIGNED, 16, -1, 8000, 1},
  {"u3",   SOX_ENCODING_UNSIGNED, 24, -1, 8000, 1},
